/* Plain JavaScript UI. Replace the data access helpers with API calls if a backend is added. */
(() => {
  'use strict';
  const D=window.HUB_DATA, C=window.CAMPUS;
  const STORAGE='iiuc-hub-v1';
  function readSaved(){try{return JSON.parse(localStorage.getItem(STORAGE))||{};}catch{return {};}}
  const saved=readSaved();
  const state={lang:saved.lang==='bn'?'bn':'en',theme:saved.theme==='dark'?'dark':'light',profile:saved.profile&&D.groups.some(g=>g.id===saved.profile.group)?saved.profile:null,stop:saved.stop||null,date:/^\d{4}-\d{2}-\d{2}$/.test(saved.date)?saved.date:'2026-10-25',versions:Array.isArray(saved.versions)?saved.versions.filter(v=>v&&['routine','bus'].includes(v.kind)&&typeof v.effective==='string'&&Number.isFinite(v.version)&&(v.kind==='bus'?Array.isArray(v.stops):v.days)):[],page:'home',day:0,teacherQuery:'',department:'All',area:'',direction:'outbound',departure:0,mapQuery:'',building:'652591398',updateKind:'routine',draft:null,upload:null,uploadUrl:null};
  const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
  const t=(en,bn)=>state.lang==='bn'?bn:en;
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=value=>state.lang==='bn'?String(value).replace(/\d/g,n=>'০১২৩৪৫৬৭৮৯'[n]):String(value);
  const group=()=>D.groups.find(g=>g.id===state.profile?.group)||D.groups[0];
  const groupLabel=g=>`${g.department} · ${t('Semester','সেমিস্টার')} ${num(g.semester)} · ${t('Section','সেকশন')} ${g.section}`;
  const versions=()=>[...Object.values(D.routines),D.bus,...state.versions];
  const routine=()=>D.activeVersion(versions(),'routine',group().id,state.date)||D.routines[group().id];
  const buses=()=>D.activeVersion(versions(),'bus','campus',state.date)||D.bus;
  const stop=()=>buses().stops.find(s=>s.id===state.stop);
  const stopName=s=>state.lang==='bn'?s.bn:s.name;
  const dateObject=date=>new Date(date+'T12:00:00');
  // Greetings follow real Bangladesh time, independently of the sample timetable date.
  const greetingClock=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Dhaka',hour:'2-digit',hourCycle:'h23'});
  function greeting(){
    const hour=Number(greetingClock.format(new Date()));
    if(hour>=5&&hour<12)return t('Good morning','সুপ্রভাত');
    if(hour>=12&&hour<17)return t('Good afternoon','শুভ অপরাহ্ণ');
    if(hour>=17&&hour<21)return t('Good evening','শুভ সন্ধ্যা');
    return t('Good night','শুভ রাত্রি');
  }
  function refreshGreeting(){
    if(!state.profile||state.page!=='home')return;
    const heading=document.querySelector('#main .page-head h1');
    const text=`${greeting()}, ${state.profile.name.split(/\s+/)[0]}.`;
    if(heading&&heading.textContent!==text)heading.textContent=text;
  }
  const dateLabel=date=>dateObject(date).toLocaleDateString(state.lang==='bn'?'bn-BD':'en-GB',{weekday:'long',day:'numeric',month:'long'});
  const demoDay=()=>dateObject(state.date).getDay();
  const routineDateLabel=()=>{const date=dateObject(state.date);date.setDate(date.getDate()-date.getDay()+state.day);return date.toLocaleDateString(state.lang==='bn'?'bn-BD':'en-GB',{weekday:'long',day:'numeric',month:'long'});};
  const classes=(day=demoDay())=>[...(routine().days[day]||[])].sort((a,b)=>a.start.localeCompare(b.start));
  const subjectName=r=>state.lang==='bn'?(r.bn||r.name):r.name;
  function time12(time){const [h,m]=time.split(':').map(Number);return `${num(h%12||12)}:${num(String(m).padStart(2,'0'))} ${h<12?t('AM','সকাল'):t('PM','বিকাল')}`;}
  function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({lang:state.lang,theme:state.theme,profile:state.profile,stop:state.stop,date:state.date,versions:state.versions}));return true;}catch{toast(t('Browser storage is full or unavailable. Changes will last for this session.','ব্রাউজারে সংরক্ষণ করা যাচ্ছে না। পরিবর্তন এই সেশন পর্যন্ত থাকবে।'));return false;}}
  let toastTimer;
  function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
  function pill(label,action,extra='',style=''){return `<button class="pill ${style}" type="button" data-action="${action}" ${extra}>${label}</button>`;}
  const badge=label=>`<span class="badge">${label}</span>`;
  const head=(title,subtitle)=>`<header class="page-head"><h1 tabindex="-1">${title}</h1><p>${subtitle}</p></header>`;
  const empty=(title,description='')=>`<div class="empty"><h3>${title}</h3><p>${description}</p></div>`;
  const navItems=[['home','Home','হোম','18e3f','9270b'],['routine','Routine','রুটিন','6d825','39f5c'],['teachers','Teachers','শিক্ষক','83f8e','cc037'],['map','Map','ম্যাপ','cc2a1','b71aa'],['more','More','আরও','ed37d','6a150']];
  function navigation(){const active=['home','routine','teachers','map'].includes(state.page)?state.page:'more';return `<nav class="bottom-nav" aria-label="${t('Main navigation','প্রধান নেভিগেশন')}">${navItems.map(([id,en,bn,icon,on])=>`<a class="nav-item ${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}><img src="assets/${active===id?on:icon}.svg" width="22" height="22" alt=""><span>${t(en,bn)}</span></a>`).join('')}</nav>`;}
  // The two original marks are viewport crops of the unaltered PDF artwork.
  // Live text keeps the new name sharp and readable in both languages and themes.
  function brandLogo(hero=false){return `<${hero?'div':'a'} class="brand${hero?' brand-hero':''}" ${hero?'role="img" aria-label="IIUC 360"':'href="#home" aria-label="IIUC 360 — '+t('Home','হোম')+'"'}><span class="brand-symbol" aria-hidden="true"><img class="brand-art brand-art-light" src="assets/iiuc-360-source.png" alt="" width="502" height="392"><img class="brand-art brand-art-dark" src="assets/iiuc-360-source.png" alt="" width="502" height="392"></span><span class="brand-wordmark" aria-hidden="true"><span>IIUC</span><strong>360</strong></span></${hero?'div':'a'}>`;}
  function topbar(onboarding=false){return `<header class="topbar${onboarding?' onboarding-topbar':''}">${onboarding?'':brandLogo()}${onboarding?'':`<nav class="desktop-nav" aria-label="${t('Main navigation','প্রধান নেভিগেশন')}">${[['home','Home','হোম'],['routine','Routine','রুটিন'],['teachers','Teachers','শিক্ষক'],['map','Campus','ক্যাম্পাস'],['more','More','আরও']].map(([id,en,bn])=>`<a class="pill ${state.page===id?'quiet':''}" href="#${id}" ${state.page===id?'aria-current="page"':''}>${t(en,bn)}</a>`).join('')}</nav>`}<div class="controls">${pill(t('বাংলা','English'),'language','aria-label="'+t('Switch to Bangla','Switch to English')+'"')}${pill(state.theme==='light'?t('Dark','ডার্ক'):t('Light','লাইট'),'theme','aria-label="'+(state.theme==='light'?'Switch to dark theme':'Switch to light theme')+'"')}</div></header>`;}
  function render(){
    document.documentElement.lang=state.lang;document.documentElement.dataset.theme=state.theme;
    document.querySelector('meta[name="theme-color"]').content=state.theme==='dark'?'#101f2a':'#edf4f7';
    if(!state.profile){app.innerHTML=`<div class="onboarding">${topbar(true)}<main id="main">${brandLogo(true)}${onboarding()}</main></div>`;return;}
    const views={home,routine:routineView,teachers:teachersView,transport:transportView,map:mapView,more:moreView,updates:updatesView,review:reviewView,published:publishedView,prayer:prayerView};
    if(!views[state.page])state.page='home';
    app.innerHTML=`<div class="shell">${topbar()}<main id="main">${views[state.page]()}</main>${navigation()}</div>`;
    if(state.page==='map')setupMap();
    if(state.page==='updates')setupDropzone();
  }
  function go(page){if(location.hash==='#'+page){state.page=page;render();}else location.hash=page;}
  function onboarding(){return `${head(t('A little about you.','আপনার সম্পর্কে একটু জানি।'),t('Enter your name and roll to get started.','শুরু করতে আপনার নাম ও রোল লিখুন।'))}${badge(t('Welcome to IIUC','IIUC-তে স্বাগতম'))}<form id="onboarding-form"><label class="form-field">${t('Full name','পূর্ণ নাম')}<input class="field" name="name" placeholder="${t('Rahim Uddin','রহিম উদ্দিন')}" autocomplete="given-name" required maxlength="60"><span class="fine">${t('Used only for your greeting.','শুধু শুভেচ্ছা জানানোর জন্য।')}</span></label><label class="form-field">${t('Student ID / roll','শিক্ষার্থীর আইডি / রোল')}<input class="field" name="roll" placeholder="C221234" autocomplete="off" spellcheck="false" required maxlength="20" pattern="[A-Za-z][0-9]{6,9}" aria-describedby="roll-help"><span id="roll-help" class="fine">${t('Your semester is identified from your roll.','আপনার রোল দিয়ে সেমিস্টার শনাক্ত করা হবে।')}</span></label><p id="onboarding-error" class="error" role="alert"></p><button class="pill primary wide submit" type="submit">${t('Get Started','শুরু করুন')} &nbsp; →</button></form><footer class="fine">${t('Assignment demo · try C221234 (semester 5), C231234 (semester 3), or C241234 (semester 1). These are sample mappings.','অ্যাসাইনমেন্ট ডেমো · C221234 (৫ম), C231234 (৩য়), অথবা C241234 (১ম) ব্যবহার করুন। এগুলো নমুনা তথ্য।')}</footer>`;}
  function classRow(r){return `<article class="class-row"><div class="time"><strong>${num(r.start)}</strong><small>${num(r.end)}</small></div><div><h3>${esc(subjectName(r))}</h3><p>${esc(r.code)} · ${t('Room','কক্ষ')} ${esc(num(r.room))}</p></div></article>`;}
  function home(){const rows=classes(),first=rows[0],s=stop(),pickup=s?.outbound[0];return `${head(`${greeting()}, ${esc(state.profile.name.split(/\s+/)[0])}.`,`${dateLabel(state.date)} · ${groupLabel(group())}`)}<div class="home-demo mobile-only">${badge(t('Demo schedule','নমুনা সময়সূচি'))}</div><div class="home-grid"><section class="home-classes"><div class="row between"><h2><span class="desktop-only">${t('Your day at a glance','এক নজরে আপনার দিন')}</span><span class="mobile-only">${t('Your next class','আপনার পরবর্তী ক্লাস')}</span></h2><span class="desktop-only">${badge(t('Demo timetable','নমুনা রুটিন'))}</span><a class="pill small mobile-only" href="#routine">${t('Routine','রুটিন')}</a></div>${first?`<article class="panel tint featured-class desktop-only"><p class="time">${num(first.start)} — ${num(first.end)}</p><h2>${esc(subjectName(first))}</h2><p>${esc(first.code)} · ${t('Room','কক্ষ')} ${esc(num(first.room))} · ${t('Section','সেকশন')} A</p><div class="row"><a class="pill" href="#routine">${t('See full routine','পুরো রুটিন দেখুন')}</a>${pill(t('Find the building','ভবনটি খুঁজুন'),'find-building','data-id="652591398"')}</div></article><div class="mobile-only">${classRow(first)}</div><div>${rows.slice(1).map(classRow).join('')}</div>`:empty(t('A little breathing room.','আজ একটু অবসর।'),t('No classes in the demo routine today.','আজ নমুনা রুটিনে কোনো ক্লাস নেই।'))}</section><aside class="home-aside"><section class="panel home-ride"><h2>${t('Your ride to campus','ক্যাম্পাসে আপনার যাত্রা')}</h2>${s?`<div class="ride-time"><strong>${time12(pickup).split(' ')[0]}</strong><small>${t('AM','সকাল')}<br>${t('Scheduled pickup · demo','নির্ধারিত সময় · নমুনা')}</small></div><p>${esc(stopName(s))} · ${t('selected stop','নির্বাচিত স্টপ')}</p>`:`<h3>${t('Where are you travelling from?','আপনি কোথা থেকে যাবেন?')}</h3><p>${t('Choose your boarding stop to see the sample bus schedule.','নমুনা বাসের সময় দেখতে আপনার স্টপ বেছে নিন।')}</p>`}<p class="fine">${t('Illustrative stops and times for your assignment.','অ্যাসাইনমেন্টের জন্য নমুনা স্টপ ও সময়।')}</p><a class="pill primary wide" href="#transport">${s?t('See my bus','আমার বাস দেখুন'):t('Choose my stop','আমার স্টপ বেছে নিন')}</a></section><section class="home-useful"><h2>${t('Useful on campus','ক্যাম্পাসে দরকারি')}</h2><div class="row equal"><a class="pill" href="#teachers">${t('Teacher contacts','শিক্ষকদের যোগাযোগ')}</a><a class="pill" href="#map">${t('Explore campus','ক্যাম্পাস দেখুন')}</a></div></section><section class="panel glass home-update"><h3>${t('Got the latest timetable?','নতুন সময়সূচি পেয়েছেন?')}</h3><p>${t('Try the upload, review and publish flow. Your demo schedule updates throughout this browser.','আপলোড, যাচাই ও প্রকাশ করে দেখুন। এই ব্রাউজারে সব সময়সূচি আপডেট হবে।')}</p><a class="pill wide" href="#updates">${t('Manage schedules','সময়সূচি ব্যবস্থাপনা')}</a></section></aside></div><p class="fine footer-note">${t('Assignment preview · sample schedules, not live university information.','অ্যাসাইনমেন্ট প্রিভিউ · নমুনা সময়সূচি, বিশ্ববিদ্যালয়ের লাইভ তথ্য নয়।')}</p>`;}
  function routineView(){const d=dateObject(state.date);d.setDate(d.getDate()-d.getDay());const dates=Array.from({length:7},(_,i)=>{const n=new Date(d);n.setDate(d.getDate()+i);return n;});const rows=classes(state.day);return `${head(t('Your week, clearly.','আপনার সপ্তাহ, সহজভাবে।'),groupLabel(group()))}<div class="routine-grid"><section class="stack"><div class="toolbar">${badge(`${t('Demo','নমুনা')} · v${num(routine().version)}`)}${pill(t('Change group','গ্রুপ পরিবর্তন'),'group','','small')}${pill(t('Print / PDF','প্রিন্ট / PDF'),'print','','small')}</div><div class="week" aria-label="${t('Choose day','দিন নির্বাচন করুন')}">${dates.map((date,i)=>pill(`<span>${date.toLocaleDateString(state.lang==='bn'?'bn-BD':'en-GB',{weekday:'short'}).slice(0,state.lang==='bn'?4:2)}</span><span>${num(date.getDate())}</span>`,'day',`data-day="${i}" aria-pressed="${i===state.day}"`,`day ${i===state.day?'primary':''}`)).join('')}</div><h2>${dates[state.day].toLocaleDateString(state.lang==='bn'?'bn-BD':'en-GB',{weekday:'long',day:'numeric',month:'long'})}</h2><div>${rows.length?rows.map(classRow).join(''):empty(t('No classes scheduled.','কোনো ক্লাস নেই।'),t('Enjoy your free day. Choose another day above.','অবসর দিন উপভোগ করুন। উপরে অন্য দিন বেছে নিন।'))}</div>${pill(t('Upload an updated routine','নতুন রুটিন আপলোড করুন'),'open-updates','data-kind="routine"','wide')}<p class="fine">${t('Published demo updates refresh this timetable and the home screen together.','প্রকাশিত ডেমো আপডেট এই রুটিন ও হোম স্ক্রিন একসাথে পরিবর্তন করে।')}</p></section><aside class="panel glass"><h2>${t('A week that works for you.','আপনার সপ্তাহ আপনার মতো।')}</h2><p>${t('Your roll selects a sample class group. Switch groups to explore another semester.','আপনার রোল নমুনা ক্লাস গ্রুপ বেছে নেয়। অন্য সেমিস্টার দেখতে গ্রুপ পরিবর্তন করুন।')}</p><div class="row between"><span>${t('Active version','সক্রিয় সংস্করণ')}</span>${badge('v'+num(routine().version))}</div><p class="fine">${t('Effective from','কার্যকর')} ${num(routine().effective)} · ${t('Demo date','ডেমো তারিখ')}: ${num(state.date)}</p></aside></div>`;}
  function teachersView(){return `${head(t('Find your teacher.','আপনার শিক্ষককে খুঁজুন।'),t('Names and contacts. Nothing extra.','নাম ও যোগাযোগের তথ্য।'))}<section class="stack"><label class="sr-only" for="teacher-search">${t('Search name or department','নাম বা বিভাগ খুঁজুন')}</label><input id="teacher-search" class="field search" type="search" placeholder="${t('Search name or department','নাম বা বিভাগ খুঁজুন')}" value="${esc(state.teacherQuery)}"><div class="toolbar">${['All','CSE','EEE','BBA','Law'].map(dep=>pill(dep==='All'?t('All','সব'):dep,'department',`data-department="${dep}" aria-pressed="${state.department===dep}"`,`small ${state.department===dep?'primary':''}`)).join('')}</div><p class="fine">${t('Sample directory · public contacts collected from IIUC faculty pages.','নমুনা তালিকা · IIUC-এর শিক্ষক পেজ থেকে সংগৃহীত প্রকাশ্য যোগাযোগ।')} <a href="https://web.iiuc.ac.bd/home/regular-faculty" target="_blank" rel="noopener">${t('View source ↗','উৎস দেখুন ↗')}</a></p><div id="teacher-results">${teacherResults()}</div></section>`;}
  function teacherResults(){const q=state.teacherQuery.toLowerCase().trim();const rows=D.teachers.filter(r=>(state.department==='All'||r.department===state.department)&&[r.name,r.bn,r.department,'computer science engineering',r.email].some(v=>v.toLowerCase().includes(q)));return rows.length?`<p class="fine">${num(rows.length)} ${t('contacts','জন শিক্ষক')}</p><div class="teacher-list">${rows.map(r=>`<article class="teacher"><h3>${esc(state.lang==='bn'?r.bn:r.name)}</h3><p>${t('Computer Science & Engineering','কম্পিউটার সায়েন্স অ্যান্ড ইঞ্জিনিয়ারিং')}</p><div class="row"><a class="pill" href="tel:+88${r.phone}">${num(r.phone)}</a><a class="pill" href="mailto:${r.email}">${t('Email','ইমেইল')}</a>${pill(t('Copy','কপি'),'copy',`data-email="${r.email}"`,'small')}</div><a class="email" href="mailto:${r.email}">${r.email}</a></article>`).join('')}</div>`:empty(t('No matching teachers.','কোনো শিক্ষক পাওয়া যায়নি।'),t('Try another name or select All. Only CSE sample contacts are included.','অন্য নাম লিখুন অথবা সব নির্বাচন করুন। নমুনায় শুধু CSE-এর শিক্ষক আছেন।'));}
  function transportView(){const s=stop(),times=s?.[state.direction]||[],selected=times[Math.min(state.departure,times.length-1)];return `${head(t('Your way to campus.','ক্যাম্পাসে যাওয়ার পথ।'),t('Choose an area, then confirm a boarding stop.','এলাকা লিখুন, তারপর বাস স্টপ নিশ্চিত করুন।'))}<div class="transport-grid"><section class="stack"><label class="form-field" for="area-search">${t('Your area','আপনার এলাকা')}<input id="area-search" class="field" type="search" placeholder="${t('e.g. Halishahar','যেমন হালিশহর')}" value="${esc(state.area)}" autocomplete="off"></label><div id="stop-results">${stopResults()}</div>${s?`<div class="panel tint"><h3>${t('Selected stop','নির্বাচিত স্টপ')} · ${esc(stopName(s))}</h3><p class="fine">${t('Illustrative stop — assignment sample.','অ্যাসাইনমেন্টের জন্য নমুনা স্টপ।')}</p>${pill(t('Change boarding stop','স্টপ পরিবর্তন করুন'),'change-stop','','wide')}</div>`:''}<p class="fine">${t('If your area is not served, choose another listed stop. Unlisted stop times stay unavailable.','আপনার এলাকায় বাস না থাকলে তালিকার অন্য স্টপ বেছে নিন। তালিকার বাইরে সময় দেখানো হবে না।')}</p>${pill(t('Update bus schedule','বাসের সময়সূচি আপডেট'),'open-updates','data-kind="bus"','wide quiet')}</section><section class="stack"><div class="row equal">${pill(t('To campus','ক্যাম্পাসের দিকে'),'direction','data-direction="outbound" aria-pressed="'+(state.direction==='outbound')+'"',state.direction==='outbound'?'primary':'')}${pill(t('Return trip','ফেরার যাত্রা'),'direction','data-direction="return" aria-pressed="'+(state.direction==='return')+'"',state.direction==='return'?'primary':'')}</div>${s?`<article class="panel">${badge(`${t('Demo timetable','নমুনা সময়সূচি')} · v${num(buses().version)}`)}<strong class="departure-time">${time12(selected)}</strong><h3>${state.direction==='outbound'?`${esc(stopName(s))} → ${t('Kumira campus','কুমিরা ক্যাম্পাস')}`:`${t('Kumira campus','কুমিরা ক্যাম্পাস')} → ${esc(stopName(s))}`}</h3><p class="fine">${state.direction==='outbound'?t('Scheduled pickup · not live vehicle tracking','নির্ধারিত সময় · লাইভ বাস ট্র্যাকিং নয়'):t('Departure from campus · arrival time at your stop is not available','ক্যাম্পাস থেকে ছাড়ার সময় · স্টপে পৌঁছানোর সময় জানা নেই')}</p></article><h2>${t('Other departures','অন্যান্য যাত্রা')}</h2><div class="row equal">${times.map((time,i)=>pill(time12(time),'departure',`data-index="${i}" aria-pressed="${i===state.departure}"`,i===state.departure?'quiet':'')).join('')}</div>${pill(t('View route & all stops','রুট ও সব স্টপ দেখুন'),'route','','wide')}`:empty(t('Your journey starts here.','এখান থেকেই যাত্রা শুরু।'),t('Select a stop to see scheduled departures.','নির্ধারিত সময় দেখতে একটি স্টপ নির্বাচন করুন।'))}</section></div>`;}
  function stopResults(){const list=D.matchStops(buses().stops,state.area);if(!state.area&&stop())return '';return list.length?list.map(s=>`<button type="button" class="stop-option" data-action="select-stop" data-id="${s.id}"><span>${esc(stopName(s))}</span><small>${t('Select stop','স্টপ বেছে নিন')} →</small></button>`).join(''):empty(t('No stop found for this area.','এই এলাকায় স্টপ পাওয়া যায়নি।'),t('Try Halishahar, Agrabad, GEC, A. K. Khan or Bhatiary.','হালিশহর, আগ্রাবাদ, GEC, এ কে খান অথবা ভাটিয়ারী লিখুন।'));}
  const buildingBn={'169724542':'কেন্দ্রীয় মসজিদ','169725438':'অডিটোরিয়াম','169725502':'কেন্দ্রীয় লাইব্রেরি','169761132':'ফার্মেসি · MDP','517840676':'CSE এক্সটেনশন','517840678':'CSE এক্সটেনশন ২','517851158':'ব্যবসায় প্রশাসন','652591398':'CSE মূল ভবন','652591402':'শরিয়াহ ও ইসলামিক স্টাডিজ','652591403':'একাডেমিক ভবন ২','652591404':'আইন','768020363':'আরবি ভাষা','1225582331':'সিভিল · CCE · ELL','1225583148':'EEE · ETE','1225587338':'প্রশাসন','1225605745':'ছাত্রী একাডেমিক জোন'};
  const buildingName=p=>state.lang==='bn'?buildingBn[p.id]||p.label:p.label;
  const labelPositions={'169724542':[380,436],'169725438':[674,276],'169725502':[658,412],'169761132':[654,238],'517840676':[207,100],'517840678':[220,40],'517851158':[653,199],'652591398':[314,315],'652591402':[667,314],'652591403':[370,366],'652591404':[657,357],'768020363':[645,157],'1225582331':[476,100],'1225583148':[267,189],'1225587338':[365,258],'1225605745':[640,600]};
  function mapView(){const current=C.desktop.places.find(p=>p.id===state.building);return `${head(t('Know your campus.','আপনার ক্যাম্পাস চিনুন।'),t('Kumira · 2D campus map','কুমিরা · দ্বিমাত্রিক ক্যাম্পাস ম্যাপ'))}<label class="sr-only" for="building-search">${t('Search building or department','ভবন বা বিভাগ খুঁজুন')}</label><input class="field search" id="building-search" type="search" placeholder="${t('Search building or department','ভবন বা বিভাগ খুঁজুন')}" value="${esc(state.mapQuery)}"><div class="map-layout"><section><div class="map-viewport" id="campus-map" role="region" aria-label="${t('Interactive campus map. Drag to pan or use zoom buttons.','ক্যাম্পাস ম্যাপ। টেনে সরান অথবা জুম বাটন ব্যবহার করুন।')}"><div class="map-world" id="map-world"><img src="assets/campus.svg" width="920" height="720" alt="${t('OpenStreetMap campus building footprints, roads, water and grounds','OpenStreetMap ক্যাম্পাসের ভবন, রাস্তা, জলাশয় ও মাঠ')}" draggable="false"><svg width="920" height="720" viewBox="0 0 920 720" aria-hidden="true" style="position:absolute;pointer-events:none">${C.desktop.places.map(p=>{const [x,y]=labelPositions[p.id];return `<line x1="${p.x}" y1="${p.y}" x2="${x}" y2="${y}" stroke="#7895a4" stroke-width="1"/>`;}).join('')}</svg>${C.desktop.places.map(p=>{const [x,y]=labelPositions[p.id];return `<button class="map-pin ${p.id===state.building?'active':''}" type="button" data-action="building" data-id="${p.id}" style="left:${x}px;top:${y}px" aria-label="${esc(buildingName(p))}">${esc(buildingName(p))}</button>`;}).join('')}</div><span class="north">N ↑</span><div class="map-tools">${pill('+','zoom-in','aria-label="Zoom in"')}${pill('−','zoom-out','aria-label="Zoom out"')}${pill('↺','map-reset','aria-label="Reset map"')}</div></div><p class="map-attribution"><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors · ODbL</a> · ${t('Department labels need campus verification.','বিভাগের নাম ক্যাম্পাসে যাচাই করা প্রয়োজন।')}</p><div class="row equal" style="margin-top:14px">${pill(t('All buildings','সব ভবন'),'all-buildings')}${pill(t('Locate me','আমার অবস্থান'),'locate')}</div><div id="map-location-status" class="fine" role="status"></div></section><aside class="map-aside stack"><div class="panel tint map-detail" id="building-detail">${buildingDetail(current)}</div><h2>${t('Campus directory','ক্যাম্পাসের ভবনসমূহ')}</h2><div class="building-list" id="building-results">${buildingResults()}</div><p class="fine">${t('Map includes the academic core and female academic zone. Zoom and drag to explore.','ম্যাপে একাডেমিক এলাকা ও ছাত্রী একাডেমিক জোন রয়েছে। জুম করে ও টেনে দেখুন।')}</p></aside></div>`;}
  function buildingDetail(p){return p?`<span class="fine">${t('Selected building','নির্বাচিত ভবন')}</span><h3>${esc(buildingName(p))}</h3><p class="fine">${t('IIUC · Kumira campus','IIUC · কুমিরা ক্যাম্পাস')}</p>`:'';}
  function buildingResults(){const q=state.mapQuery.toLowerCase().trim(),rows=C.desktop.places.filter(p=>[p.label,p.sourceName,buildingBn[p.id]].some(n=>n?.toLowerCase().includes(q)));return rows.length?rows.map(p=>`<button class="building-item ${p.id===state.building?'active':''}" data-action="building" data-id="${p.id}">${esc(buildingName(p))}</button>`).join(''):empty(t('No matching building.','কোনো ভবন পাওয়া যায়নি।'));}
  let mapState={scale:1,x:0,y:0},mapObserver;
  function transformMap(){const world=document.querySelector('#map-world');if(!world)return;world.style.transform=`translate(${mapState.x}px,${mapState.y}px) scale(${mapState.scale})`;const major=['517840678','1225582331','1225583148','517851158','169761132','652591398','169724542','169725502','1225605745'];world.querySelectorAll('.map-pin').forEach(pin=>{pin.style.fontSize=Math.max(13,10/mapState.scale)+'px';pin.style.display=mapState.scale>=1.05||major.includes(pin.dataset.id)||pin.dataset.id===state.building?'':'none';});}
  function resetMap(full=false){const viewport=document.querySelector('#campus-map');if(!viewport)return;const {width,height}=viewport.getBoundingClientRect();mapState.scale=full?Math.min(width/920,height/720):Math.min(width/600,height/480);const center=full?[460,360]:[455,245];mapState.x=width/2-center[0]*mapState.scale;mapState.y=height/2-center[1]*mapState.scale;transformMap();}
  function zoomMap(factor){const viewport=document.querySelector('#campus-map');if(!viewport)return;const {width,height}=viewport.getBoundingClientRect();const next=Math.max(.35,Math.min(3,mapState.scale*factor)),ratio=next/mapState.scale;mapState.x=width/2-(width/2-mapState.x)*ratio;mapState.y=height/2-(height/2-mapState.y)*ratio;mapState.scale=next;transformMap();}
  function selectBuilding(id,center=true){state.building=id;const p=C.desktop.places.find(b=>b.id===id);if(!p)return;document.querySelector('#building-detail').innerHTML=buildingDetail(p);document.querySelector('#building-results').innerHTML=buildingResults();document.querySelectorAll('.map-pin').forEach(el=>el.classList.toggle('active',el.dataset.id===id));if(center){const v=document.querySelector('#campus-map').getBoundingClientRect();mapState.scale=Math.max(mapState.scale,1);mapState.x=v.width/2-p.x*mapState.scale;mapState.y=v.height/2-p.y*mapState.scale;transformMap();}}
  function setupMap(){if(mapObserver)mapObserver.disconnect();resetMap();const viewport=document.querySelector('#campus-map');let drag=null;viewport.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,ox:mapState.x,oy:mapState.y};viewport.setPointerCapture(e.pointerId);});viewport.addEventListener('pointermove',e=>{if(!drag)return;mapState.x=drag.ox+e.clientX-drag.x;mapState.y=drag.oy+e.clientY-drag.y;transformMap();});const end=()=>drag=null;viewport.addEventListener('pointerup',end);viewport.addEventListener('pointercancel',end);viewport.addEventListener('wheel',e=>{if(e.ctrlKey){e.preventDefault();zoomMap(e.deltaY<0?1.12:1/1.12);}},{passive:false});let previous=viewport.clientWidth;mapObserver=new ResizeObserver(()=>{if(viewport.clientWidth!==previous){previous=viewport.clientWidth;resetMap();}});mapObserver.observe(viewport);}
  function locate(){const output=document.querySelector('#map-location-status');if(!navigator.geolocation){output.textContent=t('Location is not supported in this browser.','এই ব্রাউজারে অবস্থান জানা যায় না।');return;}output.textContent=t('Waiting for location permission…','অবস্থানের অনুমতির জন্য অপেক্ষা করছি…');navigator.geolocation.getCurrentPosition(position=>{const {latitude:lat,longitude:lon}=position.coords;if(lat<22.4922||lat>22.5001||lon<91.7177||lon>91.7234){output.textContent=t('You are outside the mapped campus area. You can still explore all buildings.','আপনি ক্যাম্পাস ম্যাপের বাইরে আছেন। সব ভবন দেখতে পারবেন।');return;}const scale=Math.min((920-48)/((91.7234-91.7177)*Math.cos(22.497*Math.PI/180)),(720-48)/(22.5001-22.4922));const ox=(920-(91.7234-91.7177)*Math.cos(22.497*Math.PI/180)*scale)/2;const x=ox+(lon-91.7177)*Math.cos(22.497*Math.PI/180)*scale,y=24+(22.5001-lat)*scale;document.querySelector('.user-marker')?.remove();const marker=document.createElement('span');marker.className='user-marker';marker.style.left=x+'px';marker.style.top=y+'px';marker.setAttribute('aria-label',t('Your approximate location','আপনার আনুমানিক অবস্থান'));document.querySelector('#map-world')?.append(marker);output.textContent=t('Approximate position. Location is not saved.','আনুমানিক অবস্থান। অবস্থান সংরক্ষণ করা হয় না।');},()=>output.textContent=t('Location unavailable or permission denied. Explore using building search.','অবস্থান পাওয়া যায়নি বা অনুমতি দেওয়া হয়নি। ভবনের নাম দিয়ে খুঁজুন।'),{timeout:10000});}
  function updatesView(){const active=state.updateKind==='bus'?buses():routine();return `${head(t('Keep your day current.','আপনার দিন থাকুক আপডেট।'),t('Schedule manager · local assignment demo','সময়সূচি ব্যবস্থাপনা · স্থানীয় অ্যাসাইনমেন্ট ডেমো'))}<div class="updates-grid"><section class="stack"><div class="row equal">${pill(t('Class routine','ক্লাস রুটিন'),'update-kind','data-kind="routine" aria-pressed="'+(state.updateKind==='routine')+'"',state.updateKind==='routine'?'primary':'')}${pill(t('Bus schedule','বাসের সময়সূচি'),'update-kind','data-kind="bus" aria-pressed="'+(state.updateKind==='bus')+'"',state.updateKind==='bus'?'primary':'')}</div><form id="update-form" class="stack"><div class="upload-zone" id="upload-zone"><h2>${t('Drop a PDF here','এখানে PDF দিন')}</h2><p>${t('or choose a file from your device','অথবা আপনার ডিভাইস থেকে ফাইল বেছে নিন')}</p><input type="file" id="pdf-file" accept="application/pdf,.pdf" aria-label="${t('Choose schedule PDF','সময়সূচির PDF বেছে নিন')}"><p id="file-status" class="fine">${state.upload?esc(state.upload.name):t('PDF up to 10 MB · stays in this browser session','সর্বোচ্চ ১০ MB PDF · শুধু এই ব্রাউজার সেশনে থাকবে')}</p></div><div class="panel warm"><h3>${t('A working demo, with sample rows.','নমুনা তথ্য দিয়ে কার্যকর ডেমো।')}</h3><p class="fine">${t('PDF text is not extracted. Your file can be opened for reference; the next step loads editable sample rows. Publishing really updates this browser’s schedule.','PDF-এর লেখা পড়া হয় না। ফাইলটি যাচাইয়ের জন্য খুলতে পারবেন; পরের ধাপে সম্পাদনাযোগ্য নমুনা তথ্য আসবে। প্রকাশ করলে এই ব্রাউজারের সময়সূচি বদলাবে।')}</p></div><label class="form-field">${t('Applies to','প্রযোজ্য')}<select class="field" name="target">${state.updateKind==='bus'?`<option value="campus">${t('All demo bus stops','সব নমুনা বাস স্টপ')}</option>`:D.groups.map(g=>`<option value="${g.id}" ${g.id===group().id?'selected':''}>${groupLabel(g)}</option>`).join('')}</select></label><label class="form-field">${t('Effective from','কার্যকর হবে')}<input class="field" type="date" name="effective" value="${state.date}" required></label><button class="pill primary wide" type="submit">${t('Load sample & review','নমুনা লোড ও যাচাই')}</button><p class="fine">${t('No PDF needed to try the sample flow. Demo date:','নমুনা ব্যবহার করতে PDF লাগবে না। ডেমো তারিখ:')} ${num(state.date)}</p></form></section><aside class="stack"><h2>${t('Currently active','বর্তমানে সক্রিয়')}</h2><section class="panel glass"><h3>${state.updateKind==='bus'?t('Demo bus schedule','নমুনা বাসের সময়সূচি'):t('Demo class routine','নমুনা ক্লাস রুটিন')} · v${num(active.version)}</h3><p>${t('Effective from','কার্যকর')} ${num(active.effective)}</p><p class="fine">${esc(active.source)}</p></section><h2>${t('Version history','সংস্করণের ইতিহাস')}</h2><div>${historyRows()}</div><p class="fine">${t('Publishing updates matching routines, home cards and bus results. Other class groups keep their own schedules. Future versions activate when the demo date reaches their effective date.','প্রকাশ করলে সংশ্লিষ্ট রুটিন, হোম কার্ড ও বাসের ফলাফল বদলাবে। অন্য গ্রুপের রুটিন অপরিবর্তিত থাকবে। ডেমো তারিখ কার্যকর তারিখে পৌঁছালে ভবিষ্যৎ সংস্করণ চালু হবে।')}</p></aside></div>`;}
  function historyRows(){const target=state.updateKind==='bus'?'campus':group().id,active=D.activeVersion(versions(),state.updateKind,target,state.date);return versions().filter(v=>v.kind===state.updateKind&&v.target===target).sort((a,b)=>b.version-a.version).map(v=>`<article class="version"><div class="row between"><h3>v${num(v.version)} · ${num(v.effective)}</h3>${badge(v.id===active?.id?t('Active','সক্রিয়'):v.effective>state.date?t('Scheduled','নির্ধারিত'):t('Previous','পূর্ববর্তী'))}</div><p>${esc(v.source)}</p>${v.id!==active?.id&&v.effective<=state.date?pill(t('Restore this version','এই সংস্করণ ফিরিয়ে আনুন'),'restore',`data-id="${esc(v.id)}"`,'small'):''}</article>`).join('');}
  function makeDraft(form){const kind=state.updateKind,target=form.get('target'),effective=form.get('effective');const base=D.activeVersion(versions(),kind,target,state.date)||(kind==='bus'?D.bus:D.routines[target]);const draft=D.clone(base);draft.id='draft';draft.effective=effective;draft.source=state.upload?.name||t('Sample update','নমুনা আপডেট');draft.version=Math.max(...versions().filter(v=>v.kind===kind&&v.target===target).map(v=>v.version))+1;draft.target=target;
    if(kind==='bus'){draft.stops.find(s=>s.id==='halishahar').outbound[0]='07:30';}
    else {for(const rows of Object.values(draft.days)){for(const r of rows){if(r.id==='algorithms'){r.start='09:00';r.end='10:20';}if(r.id==='structures'){r.start='13:00';r.end='14:20';r.room='';}if(r.id==='database')r.start='14:30';}}}
    state.draft=draft;go('review');
  }
  function reviewView(){const d=state.draft;if(!d)return `${head(t('Nothing to review yet.','যাচাইয়ের জন্য কিছু নেই।'),'')}<a class="pill primary" href="#updates">${t('Manage schedules','সময়সূচি ব্যবস্থাপনা')}</a>`;const base=D.activeVersion(versions(),d.kind,d.target,state.date);return `${head(t('Check, then publish.','যাচাই করুন, তারপর প্রকাশ।'),t('Editable sample preview · changes stay on this device','সম্পাদনাযোগ্য নমুনা প্রিভিউ · পরিবর্তন এই ডিভাইসে থাকবে'))}<section class="content-narrow stack"><div class="panel tint"><h2>${d.kind==='bus'?t('Review bus departures','বাস ছাড়ার সময় যাচাই'):t('Review your class times','ক্লাসের সময় যাচাই')}</h2><p class="fine">${d.kind==='routine'?groupLabel(D.groups.find(g=>g.id===d.target)):t('All demo stops','সব নমুনা স্টপ')}<br>${t('Effective','কার্যকর')} ${num(d.effective)} · v${num(d.version)}</p></div><form id="review-form" class="stack">${d.kind==='routine'?`<p class="fine">${t('Changes to a subject apply on every day it appears. Complete the missing room before publishing.','কোনো বিষয়ের পরিবর্তন তার সব ক্লাসের দিনে প্রযোজ্য। প্রকাশের আগে খালি কক্ষ পূরণ করুন।')}</p>${d.days[0].map(r=>`<div class="review-row"><div><h3>${esc(subjectName(r))}</h3><p>${esc(r.code)} · ${t('Previously','আগে')} ${num(base.days[0].find(b=>b.id===r.id)?.start||'')}</p><label class="form-field">${t('Room','কক্ষ')}<input class="field" name="room-${r.id}" data-row="${r.id}" data-key="room" value="${esc(r.room)}" placeholder="${t('e.g. 4203','যেমন 4203')}" required maxlength="30"></label></div><label class="form-field">${t('Starts','শুরু')}<input class="field" type="time" data-row="${r.id}" data-key="start" value="${r.start}" required></label><label class="form-field">${t('Ends','শেষ')}<input class="field" type="time" data-row="${r.id}" data-key="end" value="${r.end}" required></label></div>`).join('')}`:d.stops.map(s=>`<div class="review-row bus"><div><h3>${esc(stopName(s))}</h3><p>${t('First pickup to campus','ক্যাম্পাসের দিকে প্রথম বাস')}<br>${t('Previously','আগে')} ${time12(base.stops.find(b=>b.id===s.id).outbound[0])}</p></div><label class="form-field">${t('New time','নতুন সময়')}<input class="field" type="time" data-stop="${s.id}" value="${s.outbound[0]}" required></label></div>`).join('')}<p id="review-error" class="error" role="alert"></p>${state.uploadUrl?pill(t('Open source PDF ↗','মূল PDF খুলুন ↗'),'source','','wide'):''}<button class="pill primary wide" type="submit">${t('Publish demo update','ডেমো আপডেট প্রকাশ')}</button><a href="#updates" class="pill wide">${t('Back to schedule manager','সময়সূচি ব্যবস্থাপনায় ফিরুন')}</a><p class="fine">${t('The existing version stays active until you publish. Earlier versions remain available for rollback.','প্রকাশ না করা পর্যন্ত বর্তমান সংস্করণ সক্রিয় থাকবে। পুরোনো সংস্করণ ফিরিয়ে আনা যাবে।')}</p></form></section>`;}
  function publishDraft(form){const d=D.clone(state.draft);if(d.kind==='routine'){for(const input of form.querySelectorAll('[data-row]'))for(const rows of Object.values(d.days))for(const row of rows)if(row.id===input.dataset.row)row[input.dataset.key]=input.value.trim();const error=D.validateRoutine(d.days);if(error){document.querySelector('#review-error').textContent=error==='room'?t('Enter every room before publishing.','প্রকাশের আগে সব কক্ষ লিখুন।'):error==='overlap'?t('Some classes overlap. Adjust their start and end times.','কিছু ক্লাসের সময় মিলে যাচ্ছে। শুরু ও শেষের সময় ঠিক করুন।'):t('Every class must end after its start time.','ক্লাস শেষের সময় শুরুর সময়ের পরে হতে হবে।');return;}}
    else{for(const input of form.querySelectorAll('[data-stop]'))d.stops.find(s=>s.id===input.dataset.stop).outbound[0]=input.value;for(const s of d.stops)s.outbound.sort();}
    d.id=d.kind+'-'+Date.now();state.versions.push(d);persist();state.lastPublished=d;state.draft=null;go('published');
  }
  function publishedView(){const d=state.lastPublished;return `<section class="panel success-panel"><div class="success-mark">✓</div><h1>${t('Your day is up to date.','আপনার দিন এখন আপডেট।')}</h1><p>${d&&d.effective>state.date?t('Saved for a future date. Advance the demo date in More to see this version become active.','ভবিষ্যৎ তারিখের জন্য সংরক্ষিত। আরও পেজে ডেমো তারিখ পরিবর্তন করলে এই সংস্করণ চালু হবে।'):t('The matching schedule and home screen now use your published demo data.','সংশ্লিষ্ট সময়সূচি ও হোম স্ক্রিন এখন আপনার প্রকাশিত নমুনা তথ্য ব্যবহার করছে।')}</p>${d?badge(`v${num(d.version)} · ${num(d.effective)}`):''}<a class="pill primary wide" href="#${d?.kind==='bus'?'transport':'routine'}">${t('View updated schedule','আপডেট হওয়া সময়সূচি দেখুন')}</a><a class="pill wide" href="#updates">${t('Version history','সংস্করণের ইতিহাস')}</a><p class="fine">${t('Saved in this browser only.','শুধু এই ব্রাউজারে সংরক্ষিত।')}</p></section>`;}
  function moreView(){return `${head(t('A little more, all here.','আরও কিছু, এক জায়গায়।'),t('Campus essentials and your preferences.','ক্যাম্পাসের প্রয়োজনীয় বিষয় ও আপনার পছন্দ।'))}<div class="more-list">${[['transport','Transport','পরিবহন','Find a bus from your area.','আপনার এলাকা থেকে বাস খুঁজুন।'],['updates','Manage schedules','সময়সূচি ব্যবস্থাপনা','Upload, review and publish a demo update.','ডেমো আপডেট আপলোড, যাচাই ও প্রকাশ করুন।'],['prayer','Prayer times','নামাজের সময়','Sample jamaat times and Qibla direction.','নমুনা জামাতের সময় ও কিবলার দিক।']].map(([id,en,bn,desc,bdesc])=>`<a class="more-item" href="#${id}"><strong>${t(en,bn)} ↗</strong><p>${t(desc,bdesc)}</p></a>`).join('')}<button class="more-item" data-action="preferences"><strong>${t('Demo preferences','ডেমো পছন্দসমূহ')}</strong><p>${t('Change the demo date, class group or greeting.','ডেমো তারিখ, ক্লাস গ্রুপ বা শুভেচ্ছার নাম বদলান।')}</p></button></div><section class="panel glass content-narrow" style="margin-top:24px"><h3>${t('Made for your university assignment.','আপনার বিশ্ববিদ্যালয়ের অ্যাসাইনমেন্টের জন্য।')}</h3><p>${t('This is a frontend-only prototype. Schedules and roll mappings are samples; PDF extraction is simulated. Preferences and published updates are saved on this browser.','এটি শুধু ফ্রন্টএন্ড প্রোটোটাইপ। সময়সূচি ও রোলের তথ্য নমুনা; PDF থেকে তথ্য পড়া অনুকরণ করা হয়। পছন্দ ও প্রকাশিত আপডেট এই ব্রাউজারে থাকে।')}</p><p class="fine">${t('Demo date','ডেমো তারিখ')}: ${num(state.date)} · ${groupLabel(group())}</p>${pill(t('Reset this demo','ডেমো রিসেট করুন'),'reset-confirm','','small')}</section>`;}
  function prayerView(){return `${head(t('A moment for prayer.','নামাজের জন্য একটু সময়।'),`${t('Campus mosque','ক্যাম্পাস মসজিদ')} · ${dateLabel(state.date)}`)}<div class="routine-grid"><section class="stack"><div class="panel tint"><p>${t('Qibla direction','কিবলার দিক')}</p><h2>${t('Find your direction','আপনার দিক খুঁজুন')}</h2><p class="fine">${t('Bearing from IIUC, measured clockwise from true north.','IIUC থেকে প্রকৃত উত্তরের সাপেক্ষে ঘড়ির কাঁটার দিকে কোণ।')}</p>${pill(t('Open compass','কম্পাস দেখুন'),'compass','','wide')}</div><h2>${t('Today’s jamaat','আজকের জামাত')}</h2>${badge(t('Sample times','নমুনা সময়'))}<div>${[['Fajr','ফজর','05:10'],['Dhuhr','যোহর','13:15'],['Asr','আসর','16:30'],['Maghrib','মাগরিব','17:52'],['Isha','এশা','19:15']].map(([en,bn,time])=>`<div class="prayer-row"><span>${t(en,bn)}</span><strong>${time12(time)}</strong></div>`).join('')}</div>${pill(t('Find the central mosque','কেন্দ্রীয় মসজিদ খুঁজুন'),'find-building','data-id="169724542"','wide')}</section><aside class="panel glass"><h3>${t('A gentle pause in your day.','দিনের মাঝে একটু বিরতি।')}</h3><p>${t('These are sample jamaat times for the assignment. Check the mosque timetable for actual prayer times.','এগুলো অ্যাসাইনমেন্টের জন্য নমুনা জামাতের সময়। প্রকৃত সময়ের জন্য মসজিদের সময়সূচি দেখুন।')}</p></aside></div>`;}
  function modal(title,body){dialog.innerHTML=`<button class="pill small close" type="button" data-action="close-dialog" aria-label="${t('Close dialog','বন্ধ করুন')}">×</button><h2>${title}</h2><div class="stack">${body}</div>`;dialog.showModal();}
  function showGroup(){modal(t('Choose a demo class group','নমুনা ক্লাস গ্রুপ বেছে নিন'),`${D.groups.map(g=>pill(groupLabel(g),'select-group',`data-id="${g.id}"`,g.id===group().id?'primary wide':'wide')).join('')}<p class="fine">${t('This changes the displayed routine. Your name remains for greetings only.','এটি প্রদর্শিত রুটিন বদলাবে। আপনার নাম শুধু শুভেচ্ছার জন্য থাকবে।')}</p>`);}
  function showPreferences(){modal(t('Demo preferences','ডেমো পছন্দসমূহ'),`<form id="preferences-form" class="stack"><label class="form-field">${t('Greeting name','শুভেচ্ছার নাম')}<input name="name" class="field" value="${esc(state.profile.name)}" required maxlength="60"></label><label class="form-field">${t('Demo date','ডেমো তারিখ')}<input name="date" type="date" class="field" value="${state.date}" required></label><label class="form-field">${t('Class group','ক্লাস গ্রুপ')}<select name="group" class="field">${D.groups.map(g=>`<option value="${g.id}" ${g.id===group().id?'selected':''}>${groupLabel(g)}</option>`).join('')}</select></label><p class="fine">${t('The demo date controls which schedule version is active.','ডেমো তারিখ নির্ধারণ করে কোন সময়সূচি সক্রিয় থাকবে।')}</p><button class="pill primary wide" type="submit">${t('Save preferences','পছন্দ সংরক্ষণ')}</button></form>`);}
  function routeModal(){const s=stop(),chain=s?.id==='halishahar'?['halishahar','ak-khan','bhatiary']:['agrabad','gec','ak-khan','bhatiary'],start=Math.max(0,chain.indexOf(s?.id)),names=chain.slice(start).map(id=>stopName(buses().stops.find(p=>p.id===id)));names.push(t('IIUC · Kumira','IIUC · কুমিরা'));if(state.direction==='return')names.reverse();modal(t('Your demo route','আপনার নমুনা রুট'),`<p>${t('Illustrative route — not an official IIUC route map.','নমুনা রুট — এটি IIUC-এর অফিসিয়াল রুট নয়।')}</p><ol class="route-list">${names.map((name,i)=>`<li><strong>${num(i+1)}. ${esc(name)}</strong><span class="fine">${t('Sample stop','নমুনা স্টপ')}</span></li>`).join('')}</ol><p class="fine">${t('No travel duration or live arrival estimate is provided.','যাত্রার সময়কাল বা লাইভ আগমনের অনুমান দেখানো হয় না।')}</p>`);}
  function compassModal(){const rad=n=>n*Math.PI/180;const lat=rad(22.497),target=rad(21.4225),delta=rad(39.8262-91.7205);const bearing=(Math.atan2(Math.sin(delta),Math.cos(lat)*Math.tan(target)-Math.sin(lat)*Math.cos(delta))*180/Math.PI+360)%360;modal(t('Qibla from IIUC','IIUC থেকে কিবলা'),`<div class="compass"><span>N</span><div class="needle" style="--bearing:${bearing}deg">↑</div><small>${t('True north','প্রকৃত উত্তর')}</small></div><h3 style="text-align:center">${num(bearing.toFixed(1))}° ${t('from north','উত্তর থেকে')}</h3><p>${t('This is a fixed direction guide, not a live sensor compass. Align north with your phone’s compass, then follow the arrow.','এটি স্থির দিকনির্দেশনা, লাইভ সেন্সর কম্পাস নয়। ফোনের কম্পাস দিয়ে উত্তর মিলিয়ে তীরের দিক অনুসরণ করুন।')}</p>`);}
  async function acceptFile(file){if(!file)return;if(!file.name.toLowerCase().endsWith('.pdf')||file.size>10*1024*1024){toast(t('Choose a PDF smaller than 10 MB.','১০ MB-এর ছোট PDF বেছে নিন।'));return;}const header=new TextDecoder().decode(await file.slice(0,5).arrayBuffer());if(header!=='%PDF-'){toast(t('This file does not appear to be a PDF.','এই ফাইলটি PDF বলে মনে হচ্ছে না।'));return;}if(state.uploadUrl)URL.revokeObjectURL(state.uploadUrl);state.upload=file;state.uploadUrl=URL.createObjectURL(file);const status=document.querySelector('#file-status');if(status)status.textContent=file.name+' · '+(file.size/1024).toFixed(0)+' KB';}
  function setupDropzone(){const zone=document.querySelector('#upload-zone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');acceptFile(e.dataTransfer.files[0]);});}
  function restore(id){const old=versions().find(v=>v.id===id);if(!old)return;const restored=D.clone(old);restored.id=old.kind+'-'+Date.now();restored.version=Math.max(...versions().filter(v=>v.kind===old.kind&&v.target===old.target).map(v=>v.version))+1;restored.effective=state.date;restored.source=t('Restored from v','ফিরিয়ে আনা সংস্করণ v')+old.version;state.versions.push(restored);persist();render();toast(t('Previous schedule restored.','আগের সময়সূচি ফিরিয়ে আনা হয়েছে।'));}
  function printRoutine(){const title=t('IIUC · Class routine','IIUC · ক্লাস রুটিন'),rows=classes(state.day);const win=window.open('','_blank','width=850,height=700');if(!win){toast(t('Allow pop-ups to print the routine.','রুটিন প্রিন্ট করতে পপ-আপের অনুমতি দিন।'));return;}win.document.write(`<!doctype html><html lang="${state.lang}"><head><meta charset="utf-8"><title>${title}</title><style>body{font:14px Arial,sans-serif;padding:40px;color:#173b4a}table{border-collapse:collapse;width:100%;margin:30px 0}td,th{text-align:left;border-bottom:1px solid #ddd;padding:14px}small{color:#58717f}</style></head><body><h1>${title}</h1><p>${groupLabel(group())}</p><p>${routineDateLabel()} · v${routine().version}</p><table><thead><tr><th>${t('Time','সময়')}</th><th>${t('Subject','বিষয়')}</th><th>${t('Room','কক্ষ')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${num(r.start)}–${num(r.end)}</td><td>${esc(subjectName(r))}<br><small>${r.code}</small></td><td>${esc(r.room)}</td></tr>`).join('')}</tbody></table><p>${t('Assignment sample · not an official routine.','অ্যাসাইনমেন্টের নমুনা · অফিসিয়াল রুটিন নয়।')}</p><button onclick="window.print()">${t('Print / Save as PDF','প্রিন্ট / PDF সংরক্ষণ')}</button></body></html>`);win.document.close();}
  document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
    switch(action){
      case 'language':state.lang=state.lang==='en'?'bn':'en';persist();render();break;
      case 'theme':state.theme=state.theme==='light'?'dark':'light';persist();render();break;
      case 'day':state.day=Number(el.dataset.day);render();break;
      case 'group':showGroup();break;
      case 'select-group':state.profile.group=el.dataset.id;persist();dialog.close();render();break;
      case 'department':state.department=el.dataset.department;render();break;
      case 'copy':try{await navigator.clipboard.writeText(el.dataset.email);toast(t('Email copied.','ইমেইল কপি হয়েছে।'));}catch{modal(t('Copy email','ইমেইল কপি করুন'),`<input class="field" readonly value="${esc(el.dataset.email)}" aria-label="Email">`);dialog.querySelector('input').select();}break;
      case 'select-stop':state.stop=el.dataset.id;state.area='';state.departure=0;persist();render();toast(t('Boarding stop saved.','স্টপ সংরক্ষিত হয়েছে।'));break;
      case 'change-stop':state.area='';document.querySelector('#area-search').value='';document.querySelector('#stop-results').innerHTML=buses().stops.map(s=>`<button class="stop-option" data-action="select-stop" data-id="${s.id}"><span>${esc(stopName(s))}</span><span>→</span></button>`).join('');document.querySelector('#area-search').focus();break;
      case 'direction':state.direction=el.dataset.direction;state.departure=0;render();break;
      case 'departure':state.departure=Number(el.dataset.index);render();break;
      case 'route':routeModal();break;
      case 'open-updates':state.updateKind=el.dataset.kind;go('updates');break;
      case 'update-kind':state.updateKind=el.dataset.kind;render();break;
      case 'source':if(state.uploadUrl)window.open(state.uploadUrl,'_blank','noopener');break;
      case 'restore':restore(el.dataset.id);break;
      case 'preferences':showPreferences();break;
      case 'reset-confirm':modal(t('Reset the assignment demo?','অ্যাসাইনমেন্ট ডেমো রিসেট করবেন?'),`<p>${t('This removes your local profile, selected stop and published demo updates.','এটি আপনার স্থানীয় প্রোফাইল, স্টপ ও প্রকাশিত ডেমো আপডেট মুছে দেবে।')}</p>${pill(t('Reset demo','ডেমো রিসেট'),'reset','','primary wide')}${pill(t('Keep my data','তথ্য রাখুন'),'close-dialog','','wide')}`);break;
      case 'reset':try{localStorage.removeItem(STORAGE);}catch{}location.hash='home';location.reload();break;
      case 'close-dialog':dialog.close();break;
      case 'find-building':state.building=el.dataset.id;go('map');break;
      case 'building':selectBuilding(el.dataset.id);break;
      case 'zoom-in':zoomMap(1.25);break;
      case 'zoom-out':zoomMap(.8);break;
      case 'map-reset':resetMap();break;
      case 'all-buildings':resetMap(true);document.querySelector('#building-search').value='';state.mapQuery='';document.querySelector('#building-results').innerHTML=buildingResults();break;
      case 'locate':locate();break;
      case 'compass':compassModal();break;
      case 'print':printRoutine();break;
    }
  });
  document.addEventListener('input',event=>{const el=event.target;if(el.id==='teacher-search'){state.teacherQuery=el.value;document.querySelector('#teacher-results').innerHTML=teacherResults();}if(el.id==='area-search'){state.area=el.value;document.querySelector('#stop-results').innerHTML=stopResults();}if(el.id==='building-search'){state.mapQuery=el.value;document.querySelector('#building-results').innerHTML=buildingResults();}if(state.draft&&el.dataset.row){for(const rows of Object.values(state.draft.days))for(const r of rows)if(r.id===el.dataset.row)r[el.dataset.key]=el.value;}if(state.draft&&el.dataset.stop)state.draft.stops.find(s=>s.id===el.dataset.stop).outbound[0]=el.value;});
  document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();const main=document.querySelector('#main');main.setAttribute('tabindex','-1');main.focus();});
  document.addEventListener('change',event=>{if(event.target.id==='pdf-file')acceptFile(event.target.files[0]);});
  document.addEventListener('submit',event=>{event.preventDefault();const form=event.target,values=new FormData(form);
    if(form.id==='onboarding-form'){const name=values.get('name').trim(),roll=values.get('roll').trim().toUpperCase(),g=D.identifyRoll(roll);if(!name){document.querySelector('#onboarding-error').textContent=t('Please enter your name.','আপনার নাম লিখুন।');return;}if(!g){document.querySelector('#onboarding-error').textContent=t('This demo recognises C221…, C231… or C241… rolls. Try C221234.','এই ডেমোতে C221…, C231… অথবা C241… রোল আছে। C221234 লিখুন।');return;}state.profile={name,roll,group:g.id};state.day=demoDay();persist();state.page='home';if(location.hash==='#home')render();else go('home');}
    if(form.id==='update-form')makeDraft(values);
    if(form.id==='review-form')publishDraft(form);
    if(form.id==='preferences-form'){const name=values.get('name').trim();if(!name)return;state.profile.name=name;state.profile.group=values.get('group');state.date=values.get('date');state.day=demoDay();persist();dialog.close();render();toast(t('Preferences saved.','পছন্দ সংরক্ষিত হয়েছে।'));}
  });
  window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'home';if(state.page==='routine')state.day=demoDay();if(dialog.open)dialog.close();render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('h1')?.focus({preventScroll:true});});
  // Keep another open tab in sync with this browser's published schedules.
  window.addEventListener('storage',event=>{if(event.key===STORAGE){const next=readSaved();if(Array.isArray(next.versions))state.versions=next.versions;if(next.stop!==undefined)state.stop=next.stop;render();}});
  setInterval(refreshGreeting,60000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshGreeting();});
  window.addEventListener('focus',refreshGreeting);
  state.page=location.hash.slice(1)||'home';state.day=demoDay();render();
})();


